from pptx import Presentation
from pptx.util import Pt

prs = Presentation('/root/Awesome-Agent-Papers_processed.pptx')
print(f"Total slides: {len(prs.slides)}")
print()

for slide_idx, slide in enumerate(prs.slides):
    print(f"=== Slide {slide_idx + 1} ===")
    for shape in slide.shapes:
        if shape.has_text_frame:
            for para in shape.text_frame.paragraphs:
                text = para.text.strip()
                if not text:
                    continue
                for run in para.runs:
                    try:
                        color = str(run.font.color.rgb) if run.font.color and run.font.color.type is not None else 'inherited'
                    except:
                        color = 'inherited'
                    print(f"  '{run.text[:70]}...' " if len(run.text) > 70 else f"  '{run.text}' ",
                          f"font={run.font.name}, size={run.font.size}, bold={run.font.bold}, color={color}")

        # Check TextBox shapes specifically  
        if shape.shape_type == 17:
            text = shape.text_frame.text.strip()
            print(f"  [TextBox] pos=({shape.left/914400:.2f}in, {shape.top/914400:.2f}in) "
                  f"size=({shape.width/914400:.2f}in x {shape.height/914400:.2f}in) "
                  f"wordwrap={shape.text_frame.word_wrap}")
    print()

# Check last slide specifically
print("=== REFERENCE SLIDE DETAILS ===")
ref_slide = prs.slides[-1]
for shape in ref_slide.shapes:
    if shape.has_text_frame:
        print(f"Shape: {shape.name}")
        for para in shape.text_frame.paragraphs:
            text = para.text.strip()
            if text:
                print(f"  '{text}'")
